"""Islamiat (Ikhtiari) XII PDF77: pp.144–145 — ahadith 49 (qudsi), 50. Run: python class12_iski_page077.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p77():
    b = Builder()
    b.h('Hadith no. 49', 'حدیث نمبر 49', 'حدیث نمبر ۴۹')
    AR(b, 'عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللّٰهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ: "يَقُوْلُ اللّٰهُ تَعَالٰى اَنَا عِنْدَ ظَنِّ عَبْدِيْ بِيْ، وَاَنَا مَعَهٗ اِذَا ذَكَرَنِيْ، فَاِنْ ذَكَرَنِيْ فِيْ نَفْسِهٖ، ذَكَرْتُهٗ فِيْ نَفْسِيْ، وَاِنْ ذَكَرَنِيْ فِيْ مَلَاٍ، ذَكَرْتُهٗ فِيْ مَلَاٍ خَيْرٍ مِّنْهُمْ، وَاِنْ تَقَرَّبَ اِلَيَّ بِشِبْرٍ تَقَرَّبْتُ اِلَيْهِ ذِرَاعًا، وَاِنْ تَقَرَّبَ اِلَيَّ ذِرَاعًا، تَقَرَّبْتُ اِلَيْهِ بَاعًا، وَاِنْ اَتَانِيْ يَمْشِيْ، اَتَيْتُهٗ هَرْوَلَةً"', 'صحیح مسلم و صحیح البخاری')
    b.p('Translation: Hazrat Abu Hurayrah (may Allah be pleased with him) says that the Noble Prophet ﷺ said: Allah the Exalted says: I am according to My servant\'s opinion of Me, and I am with him when he remembers Me. When he remembers Me in his heart, I remember him in My heart; and when he remembers Me in a gathering, I remember him in a gathering better than that. When he comes one span towards Me, I come one cubit towards him; and if he comes one cubit, I come two arms\' length; and when he comes walking, I come running towards him.', 'ترجمہ: حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ فرماتے ہیں نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: اللہ تعالیٰ فرماتے ہیں میں اپنے بندے کے گمان کے ساتھ ہوتا ہوں۔ اور میں اس کے ساتھ ہوتا ہوں جب مجھے یاد کرتا ہے۔ جب مجھے وہ دل میں یاد کرتا ہے تو میں اسے دل میں یاد کرتا ہوں۔ اور جب مجھے وہ محفل میں یاد کرتا ہے تو میں اسے اس سے بہتر محفل میں یاد کرتا ہوں۔ جب وہ ایک بالشت چل کر میری طرف آتا ہے تو میں ایک گز اسکی طرف آتا ہوں۔ اور اگر وہ ایک گز آتا ہے تو میں دو ہاتھ چل کر آتا ہوں۔ اور جب وہ چل کر آتا ہے تو میں اس کی طرف دوڑ کر آتا ہوں۔', 'ژباړه: حضرت ابوهریره رضي الله عنه وايي چې نبي کریم ﷺ وفرمایل: الله تعالی فرمایي: زه د خپل بنده له ګومان سره یم، او له هغه سره یم کله چې ما یادوي. کله چې ما په زړه کې یاد کړي، زه یې په خپل زړه کې یادوم؛ او کله چې ما په غونډه کې یاد کړي، زه یې تر هغې په غوره غونډه کې یادوم. کله چې هغه یوه لوېشت ما ته راشي، زه یو ګز هغه ته ورځم؛ او که هغه یو ګز راشي، زه دوه لاسه ورځم؛ او کله چې هغه په پښو راشي، زه ورته په منډه ورځم.')
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('This blessed hadith is a hadith qudsi. A hadith qudsi is that in which the Noble Prophet ﷺ says that Allah the Exalted says that …', 'یہ حدیثِ مبارکہ حدیثِ قدسی ہے۔ حدیثِ قدسی وہ ہوتی ہے جس میں نبی کریم صلی اللہ علیہ وآلہٖ وسلم فرمائیں کہ اللہ تعالیٰ فرماتا ہے کہ ـــــ', 'دا مبارک حدیث قدسي حدیث دی. قدسي حدیث هغه دی چې په کې نبي کریم ﷺ ووایي چې الله تعالی فرمایي چې …'),
          ('In this blessed hadith the special favours of divine mercy are mentioned. Allah the Exalted loves His servants immensely. In some ahadith it comes that Allah loves His servants even more than seventy mothers. In Surah al-Baqarah it has been said that when some servant calls upon Allah, Allah answers his call.', 'اس حدیثِ مبارکہ میں رحمتِ خداوندی کی خصوصی عنایتوں کا ذکر ہوا ہے۔ اللہ تعالیٰ اپنے بندوں سے بے حد پیار کرتا ہے۔ بعض احادیث میں آتا ہے کہ اللہ اپنے بندوں سے ستر ماؤں سے بھی زیادہ پیار کرتا ہے۔ سورۃ البقرۃ میں فرمایا گیا ہے کہ جب کوئی بندہ اللہ کو پکارتا ہے تو اللہ اس کی پکار کا جواب دیتا ہے۔', 'په دې مبارک حدیث کې د الهي رحمت د ځانګړو پېرزوینو یادونه شوې. الله تعالی له خپلو بندګانو سره بې‌حده مینه کوي. په ځینو احادیثو کې راغلي چې الله له خپلو بندګانو سره تر اویا میندو زیاته مینه کوي. په سورة البقره کې ویل شوي چې کله کوم بنده الله ته غږ وکړي، الله یې غږ ته ځواب ورکوي.')])
    r1 = rec(b, 2, 144, 77, [144])
    t = Builder()
    t.p('In this hadith it has been said that when some servant remembers Allah the Exalted, Allah the Exalted too remembers him. If the servant remembers in public, Allah the Exalted mentions this servant in the gathering of the angels, and if the servant remembers in seclusion, Allah the Exalted too remembers him in solitude. In the same way, if some servant turns towards Allah the Exalted, Allah the Exalted turns towards him four times more than that. So much so that when some servant, having committed a sin, turns back towards Allah the Exalted, Allah the Exalted holds him extremely dear. Allah the Exalted loves those who repent.', 'اس حدیث میں فرمایا گیا ہے کہ جب کوئی بندہ اللہ تعالیٰ کو یاد کرے تو اللہ تعالیٰ بھی اسے یاد کرتا ہے۔ اگر بندہ جلوت میں یاد کرے تو اللہ تعالیٰ فرشتوں کی مجلس میں اس بندے کا ذکر کرتا ہے اور اگر بندہ خلوت میں یاد کرے تو اللہ تعالیٰ بھی اسے تنہائی میں یاد کرتا ہے۔ اس طرح اگر کوئی بندہ اللہ تعالیٰ کی طرف رجوع کرتا ہے تو اللہ تعالیٰ بھی اس سے چار گنا زیادہ اس کی طرف رجوع کرتا ہے۔ حتیٰ کہ جب کوئی بندہ گناہ کا ارتکاب کر کے اللہ تعالیٰ کی طرف لوٹتا ہے تو اللہ تعالیٰ اسے بے حد محبوب رکھتا ہے۔ اللہ تعالیٰ توبہ کرنے والوں کو پسند کرتا ہے۔', 'په دې حدیث کې ویل شوي چې کله کوم بنده الله تعالی یاد کړي، الله تعالی هم هغه یادوي. که بنده په ښکاره یاد کړي، الله تعالی د پرښتو په غونډه کې د دې بنده یادونه کوي؛ او که بنده په یوازیتوب کې یاد کړي، الله تعالی هم هغه په یوازیتوب کې یادوي. همداسې که کوم بنده الله تعالی ته رجوع وکړي، الله تعالی هم تر هغه څلور چنده زیات هغه ته رجوع کوي. تر دې چې کله کوم بنده له ګناه کولو وروسته الله تعالی ته راوګرځي، الله تعالی هغه ډېر محبوب ګڼي. الله تعالی توبه کوونکي خوښوي.')
    t.h('Hadith no. 50', 'حدیث نمبر 50', 'حدیث نمبر ۵۰')
    AR(t, 'عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللّٰهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ: اَلسَّاعِيْ عَلَى الْاَرْمَلَةِ وَالْمِسْكِيْنِ كَالْمُجَاهِدِ فِيْ سَبِيْلِ اللّٰهِ اَوِ الْقَآئِمِ اللَّيْلَ الصَّآئِمِ النَّهَارَ', 'صحیح مسلم و صحیح البخاری')
    t.p('Translation: It is narrated from Hazrat Abu Hurayrah (may Allah be pleased with him) that the Noble Prophet ﷺ said: the person who strives in helping the widow and the needy is like that mujahid who strives in the way of Allah, or like that person who stands in prayer at night and fasts by day.', 'ترجمہ: حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: بیوہ و مسکین کی مدد میں کوشش کرنے والا شخص اس مجاہد کی طرح ہے جو اللہ کے راستے میں جہاد کرتا ہے یا اس شخص کی طرح ہے جو رات کو قیام کرتا اور دن کو روزہ رکھتا ہے۔', 'ژباړه: له حضرت ابوهریره رضي الله عنه روایت دی چې نبي اکرم ﷺ وفرمایل: هغه څوک چې د کونډې او مسکین په مرسته کې هڅه کوي، د هغه مجاهد په څېر دی چې د الله په لاره کې جهاد کوي، یا د هغه چا په څېر دی چې شپه په لمانځه ولاړ وي او ورځ روژه نیسي.')
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('In this blessed hadith the excellence of those who treat the needy and widows well and help them has been mentioned. In Islamic teachings great rewards and honours are mentioned for those who help helpless people. The Noble Prophet ﷺ had special love for the needy. His ﷺ blessed saying too is: O Allah, keep me poor (miskin), and raise me among the poor.', 'اس حدیثِ مبارکہ میں مسکینوں اور بیواؤں کے ساتھ اچھا سلوک کرنے اور ان کی مدد کرنے والوں کی فضیلت کا ذکر کیا گیا ہے۔ اسلامی تعلیمات میں بے سہارا لوگوں کی مدد کرنے والوں کے لیے بڑے بڑے انعامات و اکرامات کا ذکر ملتا ہے۔ نبی کریم صلی اللہ علیہ وآلہٖ وسلم مسکینوں سے خاص محبت فرماتے تھے۔ آپ صلی اللہ علیہ وآلہٖ وسلم کا ارشادِ گرامی بھی ہے کہ اے اللہ مجھے مسکین ہی رکھ، مسکینوں میں ہی میرا حشر فرما۔', 'په دې مبارک حدیث کې له مسکینانو او کونډو سره د ښه چلند او د هغوی د مرستندویانو د فضیلت یادونه شوې. په اسلامي لارښوونو کې د بې‌سرپرسته خلکو د مرستندویانو لپاره د لویو انعامونو او اکرامونو یادونه شته. نبي کریم ﷺ له مسکینانو سره ځانګړې مینه درلوده. د هغه ﷺ مبارک ارشاد هم دی: اې الله، ما مسکین وساته، او له مسکینانو سره مې حشر کړه.')
    BOOK.save(77, [(2, r1), (2, rec(t, 2, 145, 77, [145]))], issues=[{'id': 'iski12-pdf077', 'unit': 2, 'printedPage': 144,
               'description': 'The definition of hadith qudsi on p.144 ends with a printed dash line ("ـــــ") — kept as printed. Cloth/background at the bottom of both scans excluded.'}])


if __name__ == '__main__':
    p77()
